"use client";

import { motion, LayoutGroup } from "framer-motion";
import { useState, useEffect } from "react";
import type { FC } from "react";

/* ---------- Types ---------- */
interface TabItem {
  id: string;
  label: string;
}

interface ContinuousTabsProps {
  tabs?: TabItem[];
  defaultActiveId?: string;
  onChange?: (id: string) => void;
}

/* ---------- Defaults ---------- */
const DEFAULT_TABS: TabItem[] = [
  { id: "home", label: "Home" },
  { id: "interactions", label: "Interactions" },
  { id: "resources", label: "Resources" },
  { id: "docs", label: "Docs" },
];

export const ContinuousTabs: FC<ContinuousTabsProps> = ({
  tabs = DEFAULT_TABS,
  defaultActiveId = "home",
  onChange,
}) => {
  const [active, setActive] = useState<string>(defaultActiveId);
  const [isMounted, setIsMounted] = useState<boolean>(false);

  useEffect(() => {
    setIsMounted(true);
  }, []);

  const handleChange = (id: string) => {
    setActive(id);
    onChange?.(id);
  };

  if (!isMounted) return null;

  return (
    <LayoutGroup>
      <nav className="shadow-[inset_0_-2px_4px_rgba(0,0,0,0.08), inset_0_1px_0_rgba(255,255,255,0.9), 0_4px_12px_rgba(0,0,0,0.03)] dark:shadow-[inset_0_-2px_4px_rgba(0,0,0,0.5), inset_0_1px_0_rgba(255,255,255,0.05), 0_10px_20px_rgba(0,0,0,0.4)] relative flex items-center gap-0.5 rounded-full border border-[#E5E5E9] bg-linear-to-b from-[#ffffff] to-[#e9e9f2] p-1 transition-all duration-300 sm:gap-1 sm:p-1.5 dark:border-zinc-800 dark:from-zinc-900 dark:to-zinc-950">
        {tabs.map((tab) => {
          const isActive = active === tab.id;

          return (
            <button
              key={tab.id}
              onClick={() => handleChange(tab.id)}
              className="relative rounded-full px-4 py-2 focus-visible:ring-2 focus-visible:ring-ring focus-visible:outline-none sm:px-6 sm:py-3"
            >
              {/* Active pill */}
              {isActive && (
                <motion.div
                  layoutId="active-pill"
                  transition={{
                    type: "spring",
                    stiffness: 380,
                    damping: 30,
                    mass: 0.9,
                  }}
                  className="absolute inset-0 rounded-full bg-[#252528] shadow-xs dark:bg-zinc-100"
                />
              )}

              {/* Text */}
              <motion.span
                layout="position"
                className={`relative z-10 text-sm font-semibold transition-colors duration-200 sm:text-base ${
                  isActive
                    ? "text-[#EDEDEC] dark:text-zinc-950"
                    : "text-[#343437] hover:text-[#62625D] dark:text-zinc-500 dark:hover:text-zinc-300"
                } `}
              >
                {tab.label}
              </motion.span>
            </button>
          );
        })}
      </nav>
    </LayoutGroup>
  );
};
